(function(){
  function C(n){ try { return Java.loadClass(n); } catch (e) { return Packages.java.lang.Class.forName(n); } }
  if (typeof AutoJS === 'undefined') { throw new Error('端点: server 侧 AutoJS 全局缺失（通道未注入）'); }
  var BR = C('net.minecraft.core.registries.BuiltInRegistries');
  if (BR === null) { throw new Error('端点: BuiltInRegistries 不可读（本用例无法取证）'); }
  var NS = 'astral_dice:';
  function scan(reg, suffix){
    var n = 0, it = reg.keySet().iterator();
    while (it.hasNext()) {
      var s = String(it.next());
      if (s.indexOf(NS) !== 0) { continue; }
      var p = s.substring(NS.length);
      if (suffix === '' || (p.length > suffix.length && p.lastIndexOf(suffix) === p.length - suffix.length)) { n++; }
    }
    return n;
  }
  return { items: scan(BR.ITEM, ''), blocks: scan(BR.BLOCK, ''), signs: scan(BR.ITEM, '_sign'), chips: scan(BR.ITEM, '_chip') };
})()
